from collections import deque
H,W=20,25;g=[[2]*W for _ in range(H)]
for r in range(4):g[r][22]=8
g[4][21:25]=[8]*4
for r in (5,6,8):g[r][21]=8
g[7][:22]=[8]*22
g[9][21:25]=[8]*4
for r in range(10,20):g[r][22]=8
# treat grid perimeter as boundary; identify non-8 components not connected to interior perimeter ring
allowed={(r,c) for r in range(1,H-1) for c in range(1,W-1) if g[r][c]==2}
seed={p for p in allowed if p[0] in (1,H-2) or p[1] in (1,W-2)}
seen=set(seed);q=deque(seed)
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if p in allowed and p not in seen:seen.add(p);q.append(p)
holes=allowed-seen
print('holes',sorted(holes))
# comps
left=set(holes)
while left:
 p=left.pop();co={p};q=[p]
 while q:
  r,c=q.pop()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   z=(r+dr,c+dc)
   if z in left:left.remove(z);co.add(z);q.append(z)
 rs=[r for r,c in co];cs=[c for r,c in co]
